#[test]
fn all_official_locale_templates_match_independent_d3_oracle_and_parse() {
    assert_eq!(SUPPORTED_TIME_LOCALES.len(), 34);
    assert_eq!(TimeLocale::NAMES, SUPPORTED_TIME_LOCALES);
    assert_eq!(TIME_LOCALE_UPSTREAM_VERSION, "d3-time-format 4.1.0");
    assert_eq!(
        TIME_LOCALE_UPSTREAM_COMMIT,
        "76cfef1da81b70404c0226ec9db9b0d56fa09461"
    );
    for (name, instant, expected) in ORACLE {
        let locale = TimeLocale::for_name(name).unwrap();
        let format = DateTimeFormat::utc(SPEC, &locale).unwrap();
        assert_eq!(
            format.format(*instant).unwrap(),
            *expected,
            "{name} {instant}"
        );
        assert_eq!(
            format.parse(expected).unwrap(),
            *instant,
            "{name}: {expected}"
        );
    }
}

#[test]
fn french_canadian_empty_periods_remain_real_data_and_ambiguous_twelve_hour_parse_rejects() {
    let locale = TimeLocale::for_name("fr-CA").unwrap();
    assert_eq!(locale.periods, ["", ""]);
    let format = DateTimeFormat::utc("%I %p", &locale).unwrap();
    assert_eq!(format.format(0).unwrap(), "12 ");
    assert!(format.parse("12 ").is_err());
    let exact = DateTimeFormat::utc("%Y-%m-%d %H %I %p", &locale).unwrap();
    assert_eq!(exact.parse("1970-01-01 00 12 ").unwrap(), 0);
    // Existing convenience locale is intentionally stable; the official
    // directory preserves D3's distinct Chinese abbreviated month data.
    assert_eq!(TimeLocale::zh_cn().short_months[0], "1月");
    assert_eq!(
        TimeLocale::for_name("zh-CN").unwrap().short_months[0],
        "一月"
    );
}
